import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>
#include <cstdint>
__device__ __forceinline__ float sigmoid_f(float x) {
    return 1.0f / (1.0f + __expf(-x));
}
__device__ __forceinline__ float4 sigmoid4_f(float4 v) {
    v.x = sigmoid_f(v.x);
    v.y = sigmoid_f(v.y);
    v.z = sigmoid_f(v.z);
    v.w = sigmoid_f(v.w);
    return v;
}
// Elementwise sigmoid: memory-bandwidth bound streaming kernel.
// Optimization: process two independent float4 values per thread from
// separated halves of the vector range. Each load/store instruction
// remains fully coalesced while doubling the number of independent
// memory transactions issued by each thread. The scalar fallback still
// handles unaligned or non-float4-divisible inputs safely.
__global__ void sigmoid_kernel(const float* __restrict__ x,
                               float* __restrict__ y,
                               const long long n,
                               const bool use_vec) {
    const long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long stride = (long long)gridDim.x * blockDim.x;
    if (use_vec) {
        const long long n4 = n >> 2;
        const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x);
        float4* __restrict__ y4 = reinterpret_cast<float4*>(y);
        const long long half = (n4 + 1) >> 1;
        for (long long i = tid; i < half; i += stride) {
            const long long j = i + half;
            float4 a = __ldcs(&x4[i]);
            if (j < n4) {
                float4 b = __ldcs(&x4[j]);
                __stcs(&y4[i], sigmoid4_f(a));
                __stcs(&y4[j], sigmoid4_f(b));
            } else {
                __stcs(&y4[i], sigmoid4_f(a));
            }
        }
    } else {
        for (long long i = tid; i < n; i += stride) {
            __stcs(&y[i], sigmoid_f(__ldcs(&x[i])));
        }
    }
}
at::Tensor sigmoid_cuda(const at::Tensor& x) {
    TORCH_CHECK(x.is_cuda(), "sigmoid_cuda: input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "sigmoid_cuda: only float32 is supported");
    at::Tensor xc = x.contiguous();
    at::Tensor y = at::empty_like(xc);
    const long long n = (long long)xc.numel();
    if (n == 0) {
        return y;
    }
    const float* x_ptr = xc.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();
    const bool use_vec =
        ((n & 3LL) == 0LL) &&
        ((reinterpret_cast<std::uintptr_t>(x_ptr) & 15) == 0) &&
        ((reinterpret_cast<std::uintptr_t>(y_ptr) & 15) == 0);
    // Fill the device while assigning two separated float4 elements to
    // each thread in the aligned case. The grid-stride loop remains as a
    // correctness safety net for arbitrarily large n, and the grid is
    // clamped below the 2^31-1 gridDim.x launch limit.
    constexpr int threads = 512;
    const long long work = use_vec ? (((n >> 2) + 1) >> 1) : n;
    long long blocks = (work + threads - 1) / threads;
    const long long max_blocks = 2147483647LL / threads;
    if (blocks > max_blocks) blocks = max_blocks;
    if (blocks < 1LL) blocks = 1LL;
    if (blocks < 1LL) blocks = 1LL;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    sigmoid_kernel<<<(unsigned int)blocks, threads, 0, stream>>>(
        x_ptr, y_ptr, n, use_vec
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
"""
cpp_src = "at::Tensor sigmoid_cuda(const at::Tensor& x);"
_ext = load_inline(
    name="pure_cuda_sigmoid_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["sigmoid_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _ext.sigmoid_cuda(x)

